from collections import deque
seen=set(); comps=[]
for r,c in zip(*np.where(a==9)):
 if (r,c) in seen: continue
 q=deque([(r,c)]); seen.add((r,c)); comp=[]
 while q:
  x,y=q.popleft(); comp.append((x,y))
  for dx,dy in [(1,0),(-1,0),(0,1),(0,-1)]:
   z=(x+dx,y+dy)
   if 0<=z[0]<16 and 0<=z[1]<16 and a[z]==9 and z not in seen: seen.add(z);q.append(z)
 comps.append(comp)
[(len(x),(min(r for r,c in x),max(r for r,c in x),min(c for r,c in x),max(c for r,c in x))) for x in comps]

